import{af as s,ad as o,z as h,J as d,K as t,y as a,x as i,ab as l}from"./chunks/framework.D-2fLa7v.js";const w=JSON.parse('{"title":"Manage Sharing","description":"","frontmatter":{"outline":"deep","order":9},"headers":[],"relativePath":"apps/admin/devices/sharing.md","filePath":"apps/admin/devices/sharing.md"}'),c={name:"apps/admin/devices/sharing.md"};function g(p,e,m,u,f,b){const n=o("DeviceCompatibilityV3"),r=o("LinkWithDestination");return h(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794310198000"},[e[8]||(e[8]=t("h1",{id:"manage-sharing",tabindex:"-1"},[a("Manage Sharing "),t("a",{class:"header-anchor",href:"#manage-sharing","aria-label":'Permalink to "Manage Sharing"'},"​")],-1)),i(n,{float:"right"}),e[9]||(e[9]=t("p",null,[a("Sharing allows you to share a period of data that has been received from a device with other users publicly "),t("a",{href:"/docs/pr/40/apps/chasm/share/"},"via a link"),a(".")],-1)),t("p",null,[e[0]||(e[0]=a("On ",-1)),i(r,{href:"https://admin.lightbug.cloud/#/pages/devices",label:"the devices admin page",destination:"ADMIN"}),e[1]||(e[1]=a(", open the device's ",-1)),e[2]||(e[2]=t("strong",null,"More actions",-1)),e[3]||(e[3]=a(" menu and choose ",-1)),e[4]||(e[4]=t("strong",null,"Shared access",-1)),e[5]||(e[5]=a(" in the ",-1)),e[6]||(e[6]=t("strong",null,"Connectivity",-1)),e[7]||(e[7]=a(" section.",-1))]),e[10]||(e[10]=l('<p>Sharing supports one device at a time. Check the device shown under <strong>Sharing data for</strong> before creating a share.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2026/11/screenshots/devices-share-e9133f54-4ec8-4685-82b8-f36315c36862.png" alt="Share device data dialog showing the selected device, message type, time range, and optional name" width="800" tabindex="0"><figcaption>Share device data dialog showing the selected device, message type, time range, and optional name</figcaption></figure><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><p>The selection screen allows you to choose the time period to share, and the type of data to include.</p><ul><li><strong>Message type</strong>: Use <code>*</code> to include all messages, or enter a numeric <a href="/docs/pr/40/devices/api/messages/">message type from the device communication protocol</a>.</li><li><strong>Start time</strong>: The start time of the data to share, based on the time received by the server.</li><li><strong>End time</strong>: The end time of the data to share, based on the time received by the server.</li><li><strong>Name (optional)</strong>: A name of up to 255 characters to help identify the share and show on the share page.</li></ul><h3 id="time-selection" tabindex="-1">Time selection <a class="header-anchor" href="#time-selection" aria-label="Permalink to &quot;Time selection&quot;">​</a></h3><p>The dialog starts with <strong>Last 1 hour</strong> in your local timezone. Use <strong>Quick time range</strong> to choose <strong>Today</strong> or a recent period, such as <strong>Last 6 hours</strong> or <strong>Last 24 hours</strong>. Today starts at midnight in the selected time format, up to a maximum of 24 elapsed hours.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2026/11/screenshots/devices-share-time-selection-c02e310a-5867-4192-8d09-85748daa1f3a.png" alt="Quick time range menu showing Today and recent periods from five minutes to 24 hours" width="550" tabindex="0"><figcaption>Quick time range menu showing Today and recent periods from five minutes to 24 hours</figcaption></figure><p>You can also edit <strong>Start time</strong> and <strong>End time</strong> directly, including seconds. The start must be before the end, and a share can cover at most <strong>24 hours</strong>.</p><p>Choose <strong>UTC</strong> or <strong>Local</strong> under <strong>Input time format</strong>. The local timezone is shown beside Local, and each time field shows both local and UTC values underneath. Switching format converts the displayed times without changing the selected period.</p><p>To paste a timestamp, use an ISO value such as <code>2026-11-05T13:43:25Z</code> or <code>2026-11-05T14:43:25+01:00</code>, or an unambiguous month-name date such as <code>Nov 5, 2026</code>. Values without a timezone use the selected input format. Slash-separated numeric dates are not supported when pasting. If a local time is ambiguous because the clocks change, use an ISO timestamp with an explicit offset.</p><h3 id="create-the-share" tabindex="-1">Create the share <a class="header-anchor" href="#create-the-share" aria-label="Permalink to &quot;Create the share&quot;">​</a></h3><p>Clicking the <code>Share</code> button will create the share, and provide you with a link to access it, if there is data available for the selected period.</p><p>Use <strong>Copy</strong> to copy the link or <strong>Open share</strong> to view it. Anyone with the link can view the shared data without signing in, so check the device, message type, and time range before sharing the link.</p><p>The URL is made up of the device ID, start time, end time, and a random token to prevent guessing of URLs.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2026/11/share-created-confirmation.svg" alt="Share created confirmation with the share link, Copy button, and Open share link" width="800" tabindex="0"><figcaption>Share created confirmation with the share link, Copy button, and Open share link</figcaption></figure><h2 id="viewing" tabindex="-1">Viewing <a class="header-anchor" href="#viewing" aria-label="Permalink to &quot;Viewing&quot;">​</a></h2><p>Shares will be published to <a href="https://share.chasm.cloud" target="_blank" rel="noreferrer">share.chasm.cloud</a> which itself is <a href="/docs/pr/40/apps/chasm/share/">fully documented on this site</a>, and can be viewed without authentication.</p><p>Some example share URLs for RH2 devices:</p><ul><li><a href="https://share.chasm.cloud/#12916041/20260212-170900-20260212-171500-htNJ4Uuz5hM7zOb45Hw0" target="_blank" rel="noreferrer">A 5 minute drive through Bristol @ 1Hz</a></li><li><a href="https://share.chasm.cloud/#12916041/20260212-124500-20260212-134500-5QoJIuLTbH76C9PlINmS" target="_blank" rel="noreferrer">A 50 minute walk in Bristol @ 1Hz</a></li><li><a href="https://share.chasm.cloud/#13671375/20260125-151718-20260125-152439-1EBYuf1nYgfqfDJ1lAVX" target="_blank" rel="noreferrer">Sat stationary on a rock on Dartmoor</a></li></ul><p>And for other devices:</p><ul><li>Android: <a href="https://share.chasm.cloud/#13683726/20260114-164117-20260114-164627-OLlSHUMJvbY13z4TWtGZ" target="_blank" rel="noreferrer">A 5 minute walk including BLE data</a></li></ul>',22))])}const k=s(c,[["render",g]]);export{w as __pageData,k as default};
